-- PYTHON MODEL on actual Room schema; NOT an Android Room dump.
BEGIN TRANSACTION;
CREATE TABLE `audit_log` (`id` TEXT NOT NULL, `action` TEXT NOT NULL, `auditTable` TEXT NOT NULL, `recordId` TEXT NOT NULL, `recordSummary` TEXT NOT NULL, `oldValue` TEXT NOT NULL, `newValue` TEXT NOT NULL, `employeeId` TEXT NOT NULL, `employeeName` TEXT NOT NULL, `sourceType` TEXT NOT NULL DEFAULT '', `sourceId` TEXT NOT NULL DEFAULT '', `sourceVersion` INTEGER NOT NULL DEFAULT 1, `writeId` TEXT NOT NULL DEFAULT '', `createdAt` INTEGER NOT NULL, `canUndo` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `budgets` (`id` TEXT NOT NULL, `periodType` TEXT NOT NULL, `periodStart` INTEGER NOT NULL, `periodEnd` INTEGER NOT NULL, `budgetType` TEXT NOT NULL, `category` TEXT NOT NULL, `targetAmount` REAL NOT NULL, `note` TEXT NOT NULL, `isActive` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `cash_denominations` (`id` TEXT NOT NULL, `reconciliationId` TEXT NOT NULL, `denominationValue` REAL NOT NULL, `count` INTEGER NOT NULL, `subtotal` REAL NOT NULL, `isCoin` INTEGER NOT NULL, `denomination_value_minor` INTEGER NOT NULL DEFAULT 0, `subtotal_minor` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`), FOREIGN KEY(`reconciliationId`) REFERENCES `cash_reconciliation_sessions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `cash_reconciliation_sessions` (`id` TEXT NOT NULL, `employeeId` TEXT NOT NULL, `employeeName` TEXT NOT NULL, `openingBalance` REAL NOT NULL, `totalSales` REAL NOT NULL, `totalRefunds` REAL NOT NULL, `totalCashIn` REAL NOT NULL, `totalCashOut` REAL NOT NULL, `expectedBalance` REAL NOT NULL, `actualCountedBalance` REAL NOT NULL, `variance` REAL NOT NULL, `varianceReason` TEXT NOT NULL, `status` TEXT NOT NULL, `startedAt` INTEGER NOT NULL, `endedAt` INTEGER, `notes` TEXT NOT NULL, `opening_balance_minor` INTEGER NOT NULL DEFAULT 0, `total_sales_minor` INTEGER NOT NULL DEFAULT 0, `total_refunds_minor` INTEGER NOT NULL DEFAULT 0, `total_cash_in_minor` INTEGER NOT NULL DEFAULT 0, `total_cash_out_minor` INTEGER NOT NULL DEFAULT 0, `expected_balance_minor` INTEGER NOT NULL DEFAULT 0, `actual_counted_balance_minor` INTEGER NOT NULL DEFAULT 0, `variance_minor` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE TABLE `cash_register` (`id` TEXT NOT NULL, `balance` REAL NOT NULL, `balance_minor` INTEGER NOT NULL DEFAULT 0, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `cash_register_movements` (`id` TEXT NOT NULL, `movementType` TEXT NOT NULL, `amount` REAL NOT NULL, `amount_minor` INTEGER NOT NULL DEFAULT 0, `balanceBefore` REAL NOT NULL, `balance_before_minor` INTEGER NOT NULL DEFAULT 0, `balanceAfter` REAL NOT NULL, `balance_after_minor` INTEGER NOT NULL DEFAULT 0, `referenceId` TEXT NOT NULL, `note` TEXT NOT NULL, `source_type` TEXT NOT NULL DEFAULT '', `source_id` TEXT NOT NULL DEFAULT '', `source_version` INTEGER NOT NULL DEFAULT 1, `write_id` TEXT NOT NULL DEFAULT '', `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `categories` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `client_credits` (`id` TEXT NOT NULL, `clientId` TEXT NOT NULL, `amount` REAL NOT NULL, `amount_minor` INTEGER NOT NULL DEFAULT 0, `note` TEXT NOT NULL, `sourcePaymentId` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `employeeId` TEXT NOT NULL, `employeeName` TEXT NOT NULL, `isDirty` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `client_reminders` (`id` TEXT NOT NULL, `clientId` TEXT NOT NULL, `note` TEXT NOT NULL, `reminderAt` INTEGER NOT NULL, `isDone` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`clientId`) REFERENCES `clients`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `client_rfm_cache` (`clientId` TEXT NOT NULL, `recencyScore` INTEGER NOT NULL, `frequencyScore` INTEGER NOT NULL, `monetaryScore` INTEGER NOT NULL, `daysSinceLastPurchase` INTEGER NOT NULL, `totalInvoiceCount` INTEGER NOT NULL, `totalSpent` REAL NOT NULL, `avgInvoiceValue` REAL NOT NULL, `segment` TEXT NOT NULL, `totalProfit` REAL NOT NULL, `firstPurchaseAt` INTEGER NOT NULL, `lastPurchaseAt` INTEGER NOT NULL, `customerLifespanDays` INTEGER NOT NULL, `calculatedAt` INTEGER NOT NULL, PRIMARY KEY(`clientId`), FOREIGN KEY(`clientId`) REFERENCES `clients`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `clients` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `phone` TEXT NOT NULL, `nameSearch` TEXT NOT NULL DEFAULT '', `phoneSearch` TEXT NOT NULL DEFAULT '', `address` TEXT NOT NULL, `workplace` TEXT NOT NULL, `generalNote` TEXT NOT NULL, `clientType` TEXT NOT NULL, `carType` TEXT NOT NULL, `bankAccount` TEXT NOT NULL, `specialty` TEXT NOT NULL, `secondaryPhones` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `createdBy` TEXT NOT NULL, `isDirty` INTEGER NOT NULL, PRIMARY KEY(`id`));
