CREATE TABLE `commission_payments` (`id` TEXT NOT NULL, `clientId` TEXT NOT NULL, `clientName` TEXT NOT NULL, `invoiceIds` TEXT NOT NULL, `totalAmount` REAL NOT NULL, `bankName` TEXT NOT NULL, `transactionRef` TEXT NOT NULL, `paidAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `cost_allocations` (`id` TEXT NOT NULL, `itemId` TEXT NOT NULL, `sourceType` TEXT NOT NULL, `sourceId` TEXT NOT NULL, `allocatedAmount` REAL NOT NULL, `perUnitCost` REAL NOT NULL, `quantityAffected` INTEGER NOT NULL, `method` TEXT NOT NULL, `note` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`itemId`) REFERENCES `inventory_items`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `customer_profiles` (`organization_id` TEXT NOT NULL, `party_id` TEXT NOT NULL, `segment` TEXT NOT NULL, `age_years` INTEGER, `purchase_contact_name` TEXT NOT NULL, `business_activity` TEXT NOT NULL, `workplace_name` TEXT NOT NULL, `shop_name` TEXT NOT NULL, `workshop_name` TEXT NOT NULL, `vehicle_models` TEXT NOT NULL, `workshop_worker_count` INTEGER, `updated_at` INTEGER NOT NULL, `sync_revision` INTEGER NOT NULL, `dirty` INTEGER NOT NULL, PRIMARY KEY(`organization_id`, `party_id`), FOREIGN KEY(`party_id`) REFERENCES `clients`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT );
CREATE TABLE `educational_topic_targets` (`organization_id` TEXT NOT NULL, `topic_id` TEXT NOT NULL, `target_type` TEXT NOT NULL, `target_value` TEXT NOT NULL, PRIMARY KEY(`organization_id`, `topic_id`, `target_type`, `target_value`), FOREIGN KEY(`organization_id`, `topic_id`) REFERENCES `educational_topics`(`organization_id`, `topic_id`) ON UPDATE CASCADE ON DELETE CASCADE );
CREATE TABLE `educational_topics` (`organization_id` TEXT NOT NULL, `topic_id` TEXT NOT NULL, `title` TEXT NOT NULL, `summary` TEXT NOT NULL, `full_content` TEXT NOT NULL, `category` TEXT NOT NULL, `is_active` INTEGER NOT NULL, `created_by_user_id` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `is_dirty` INTEGER NOT NULL, `deleted_at` INTEGER, PRIMARY KEY(`organization_id`, `topic_id`));
CREATE TABLE `expense_revision_history` (`organization_id` TEXT NOT NULL, `expense_id` TEXT NOT NULL, `server_version` INTEGER NOT NULL, `previous_version` INTEGER, `write_id` TEXT NOT NULL, `before_content_hash` TEXT, `after_content_hash` TEXT NOT NULL, `actor_id` TEXT NOT NULL, `changed_at` INTEGER NOT NULL, PRIMARY KEY(`organization_id`, `expense_id`, `server_version`));
CREATE TABLE `expenses` (`id` TEXT NOT NULL, `category` TEXT NOT NULL, `item` TEXT NOT NULL, `amount` REAL NOT NULL, `note` TEXT NOT NULL, `date` INTEGER NOT NULL, `isDirty` INTEGER NOT NULL, `lifecycle_state` TEXT NOT NULL DEFAULT 'ACTIVE', `voided_at` INTEGER, `void_reason` TEXT, `reversal_write_id` TEXT, `amount_minor` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE TABLE `financial_inbox` (`event_id` TEXT NOT NULL, `organization_id` TEXT NOT NULL, `aggregate_id` TEXT NOT NULL, `aggregate_version` INTEGER NOT NULL, `sequence` INTEGER NOT NULL, `operation_type` TEXT NOT NULL, `payload_version` INTEGER NOT NULL, `schema_version` INTEGER NOT NULL, `payload` TEXT NOT NULL, `occurred_at` INTEGER NOT NULL, `recorded_at` INTEGER NOT NULL, `server_revision` INTEGER NOT NULL, `apply_state` TEXT NOT NULL, `apply_reason` TEXT NOT NULL DEFAULT '', `received_at` INTEGER NOT NULL, `applied_at` INTEGER, PRIMARY KEY(`event_id`));
CREATE TABLE `financial_outbox` (`event_id` TEXT NOT NULL, `organization_id` TEXT NOT NULL, `write_id` TEXT NOT NULL, `aggregate_id` TEXT NOT NULL, `aggregate_version` INTEGER NOT NULL, `sequence` INTEGER NOT NULL, `operation_type` TEXT NOT NULL, `payload_version` INTEGER NOT NULL DEFAULT 1, `schema_version` INTEGER NOT NULL DEFAULT 1, `payload` TEXT NOT NULL, `occurred_at` INTEGER NOT NULL, `recorded_at` INTEGER NOT NULL, `created_at` INTEGER NOT NULL, `sync_state` TEXT NOT NULL DEFAULT 'PENDING', `attempt_count` INTEGER NOT NULL DEFAULT 0, `next_attempt_at` INTEGER NOT NULL DEFAULT 0, `last_error` TEXT NOT NULL DEFAULT '', `server_revision` INTEGER, `synced_at` INTEGER, PRIMARY KEY(`event_id`));
CREATE TABLE `forecast_cache` (`id` TEXT NOT NULL, `forecastType` TEXT NOT NULL, `granularity` TEXT NOT NULL, `targetDate` INTEGER NOT NULL, `predictedValue` REAL NOT NULL, `lowerBound` REAL NOT NULL, `upperBound` REAL NOT NULL, `confidenceLevel` REAL NOT NULL, `method` TEXT NOT NULL, `basedOnDataPoints` INTEGER NOT NULL, `computedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `goods_receipt_lines` (`id` TEXT NOT NULL, `goods_receipt_id` TEXT NOT NULL, `purchase_order_line_id` TEXT NOT NULL, `inventory_item_id` TEXT, `received_quantity` INTEGER NOT NULL, `accepted_quantity` INTEGER NOT NULL, `rejected_quantity` INTEGER NOT NULL, `unit_cost_minor` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`goods_receipt_id`) REFERENCES `goods_receipts`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`purchase_order_line_id`) REFERENCES `purchase_order_lines`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT );
CREATE TABLE `goods_receipts` (`id` TEXT NOT NULL, `organization_id` TEXT NOT NULL, `purchase_order_id` TEXT NOT NULL, `receipt_number` TEXT NOT NULL, `received_at` INTEGER NOT NULL, `received_by` TEXT NOT NULL, `received_by_name` TEXT NOT NULL, `note` TEXT NOT NULL, `write_id` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`purchase_order_id`) REFERENCES `purchase_orders`(`id`) ON UPDATE NO ACTION ON DELETE RESTRICT );
CREATE TABLE `home_event_states` (`organization_id` TEXT NOT NULL, `user_id` TEXT NOT NULL, `event_key` TEXT NOT NULL, `seen_at` INTEGER, `snoozed_until` INTEGER, `dismissed_at` INTEGER, PRIMARY KEY(`organization_id`, `user_id`, `event_key`));
CREATE TABLE `home_quick_action_order` (`organization_id` TEXT NOT NULL, `user_id` TEXT NOT NULL, `action_id` TEXT NOT NULL, `position` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, PRIMARY KEY(`organization_id`, `user_id`, `action_id`));
CREATE TABLE `inventory_cost_outbox` (`id` TEXT NOT NULL, `organization_id` TEXT NOT NULL, `command_id` TEXT NOT NULL, `cost_revision_id` TEXT NOT NULL, `sync_state` TEXT NOT NULL, `attempt_count` INTEGER NOT NULL, `next_attempt_at` INTEGER NOT NULL, `last_error` TEXT, `ack_sequence` INTEGER, `acknowledged_at` INTEGER, `created_at` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `inventory_cost_revaluation_events` (`id` TEXT NOT NULL, `item_id` TEXT NOT NULL, `quantity_before` INTEGER NOT NULL, `old_unit_cost_minor` INTEGER NOT NULL, `new_unit_cost_minor` INTEGER NOT NULL, `revaluation_difference_minor` INTEGER NOT NULL, `source_type` TEXT NOT NULL, `source_id` TEXT NOT NULL, `source_version` INTEGER NOT NULL DEFAULT 1, `actor_id` TEXT NOT NULL DEFAULT '', `actor_name` TEXT NOT NULL DEFAULT '', `occurred_at` INTEGER NOT NULL, `write_id` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`item_id`) REFERENCES `inventory_items`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `inventory_cost_revisions` (`cost_revision_id` TEXT NOT NULL, `organization_id` TEXT NOT NULL, `item_id` TEXT NOT NULL, `source_type` TEXT NOT NULL, `source_id` TEXT NOT NULL, `source_line_id` TEXT, `revision_kind` TEXT NOT NULL, `direct_purchase_cost_minor` INTEGER NOT NULL, `landed_cost_per_base_unit_minor` INTEGER NOT NULL, `approved_inventory_cost_minor` INTEGER NOT NULL, `currency_code` TEXT NOT NULL, `exchange_rate_snapshot` TEXT NOT NULL, `allocation_basis` TEXT NOT NULL, `allocation_residual_minor` INTEGER NOT NULL, `is_provisional` INTEGER NOT NULL, `reverses_cost_revision_id` TEXT, `command_id` TEXT NOT NULL, `idempotency_key` TEXT NOT NULL, `cost_sequence` INTEGER, `approved_at` INTEGER NOT NULL, `recorded_at` INTEGER NOT NULL, `created_by` TEXT NOT NULL, `device_id` TEXT NOT NULL, `contract_version` INTEGER NOT NULL, PRIMARY KEY(`cost_revision_id`), FOREIGN KEY(`item_id`) REFERENCES `inventory_items`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION );
CREATE TABLE `inventory_items` (`id` TEXT NOT NULL, `partNumber` TEXT NOT NULL, `name` TEXT NOT NULL, `barcode` TEXT NOT NULL, `nameSearch` TEXT NOT NULL DEFAULT '', `partNumberSearch` TEXT NOT NULL DEFAULT '', `barcodeSearch` TEXT NOT NULL DEFAULT '', `unitId` TEXT, `linkedUnitItemId` TEXT, `isUnitItem` INTEGER NOT NULL, `quantityPerUnit` REAL NOT NULL, `isService` INTEGER NOT NULL, `buyPrice` REAL NOT NULL, `buy_price_minor` INTEGER NOT NULL DEFAULT 0, `sellPrice` REAL NOT NULL, `sell_price_minor` INTEGER NOT NULL DEFAULT 0, `quantity` INTEGER NOT NULL, `minQuantity` INTEGER NOT NULL, `location` TEXT NOT NULL, `note` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `isDirty` INTEGER NOT NULL, `is_archived` INTEGER NOT NULL DEFAULT 0, `archived_at` INTEGER, `archived_by` TEXT, PRIMARY KEY(`id`));
CREATE TABLE `inventory_movements` (`id` TEXT NOT NULL, `itemId` TEXT NOT NULL, `invoiceId` TEXT NOT NULL, `clientId` TEXT NOT NULL, `movementType` TEXT NOT NULL, `quantity` INTEGER NOT NULL, `quantityBefore` INTEGER NOT NULL, `quantityAfter` INTEGER NOT NULL, `unitPrice` REAL NOT NULL, `unit_price_minor` INTEGER NOT NULL DEFAULT 0, `note` TEXT NOT NULL, `shipmentId` TEXT NOT NULL, `source_type` TEXT NOT NULL DEFAULT '', `source_id` TEXT NOT NULL DEFAULT '', `source_version` INTEGER NOT NULL DEFAULT 1, `write_id` TEXT NOT NULL DEFAULT '', `organization_id` TEXT, `movement_kind` TEXT, `signed_base_quantity` INTEGER, `source_line_id` TEXT, `command_id` TEXT, `idempotency_key` TEXT, `posting_group_id` TEXT, `reverses_movement_id` TEXT, `conversion_factor_snapshot` TEXT, `occurred_at` INTEGER, `recorded_at` INTEGER, `server_accepted_at` INTEGER, `server_sequence` INTEGER, `created_by` TEXT, `device_id` TEXT, `contract_version` INTEGER NOT NULL DEFAULT 1, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`itemId`) REFERENCES `inventory_items`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION );
