CREATE TABLE `inventory_units` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `quantityPerUnit` REAL NOT NULL, `unitType` TEXT NOT NULL, `quantity_per_unit_base` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE TABLE `inventory_write_guards` (`id` TEXT NOT NULL, `organization_id` TEXT NOT NULL, `command_id` TEXT NOT NULL, `idempotency_key` TEXT NOT NULL, `operation` TEXT NOT NULL, `actor_id` TEXT NOT NULL, `actor_name` TEXT NOT NULL, `created_at` INTEGER NOT NULL, PRIMARY KEY(`id`));
